      }
    ],
    "Examples": [
      {
        "Description": "Change a process description",
        "Command": "uip or processes update c3d4e5f6-0000-0000-0000-000000000001 --description \"Monthly invoice batch\"",
        "Output": {
          "Code": "ProcessUpdated",
          "Data": {
            "Key": "c3d4e5f6-0000-0000-0000-000000000001",
            "Name": "InvoiceProcessing",
            "Status": "Updated successfully"
          }
        }
      }
    ],
    "Subcommands": [],
    "GlobalOptions": [
      {
        "Flags": "--output <table|json|yaml|plain>",
        "Description": "Output format (default: json)"
      },
      {
        "Flags": "--output-filter <expression>",
        "Description": "JMESPath expression to filter output"
      },
      {
        "Flags": "--log-level <debug|info|warn|error>",
        "Description": "Log level threshold (default: info)"
      },
      {
        "Flags": "--log-file <path>",
        "Description": "Write logs to file instead of stderr"
      }
    ]
  }
}

{
  "Result": "Success",
  "Code": "Help",
  "Data": {
    "Command": "jobs",
    "Description": "Manage UiPath Orchestrator jobs (process executions). Start jobs from processes, monitor execution, check logs and traces.",
    "Usage": "uip or jobs [options] [command]",
    "Arguments": [],
    "Options": [
      {
        "Flags": "-h, --help",
        "Description": "display help for command"
      }
    ],
    "Subcommands": [
      {
        "Name": "list [options]",
        "Description": "List jobs. Returns job key, state, process name, timing, and machine info. Use --state to filter by job state (Pending, Running, Successful, Faulted, Stopped, Stopping, Suspended, Resumed, Terminating). Provide --folder-path or --folder-key to scope to a folder, or omit for cross-folder listing."
      },
      {
        "Name": "get [options] <job-key>",
        "Description": "Get a job by its key (GUID). Returns state, input/output arguments, timing, machine info, and error details if faulted. If the job is in Pending state, also includes troubleshooting reasons (robot availability, capacity, etc.). No folder context needed — the key is globally unique. Use 'jobs list' to find job keys."
      },
      {
        "Name": "start [options] <process-key>",
        "Description": "Start a job for a process. Returns the created job(s) with keys. The <process-key> is the GUID from 'processes list' (not 'packages list'). Folder is optional — if not provided, it is inferred from the process. Use 'packages entry-points' to see input/output argument schemas for the process."
      },
      {
        "Name": "stop [options] <job-keys...>",
        "Description": "Stop one or more running or pending jobs. With a single key: respects --strategy (SoftStop or Kill). With multiple keys: always force-stops (Kill) using the bulk API. No folder context needed — resolved from job key."
      },
      {
        "Name": "restart [options] <job-key>",
        "Description": "Restart a faulted or stopped job. Creates a new job from the same process. No folder context needed — resolved from job key."
      },
      {
        "Name": "resume [options] <job-key>",
        "Description": "Resume a suspended job. Jobs become suspended when they use the 'Suspend' activity (long-running workflows that wait for external input). Optionally pass new --input-arguments to continue execution with updated data. No folder context needed — resolved from job key."
      },
      {
        "Name": "logs [options] <job-key>",
        "Description": "Get robot execution logs for a job. Filter by --level to quickly find errors. Folder context is inferred from the job key. Logs are returned newest-first."
      },
      {
        "Name": "traces [options] <job-key>",
        "Description": "Get LlmOps execution traces for an agentic job. Shows LLM interactions, tool calls, and agent decisions made during execution. Only available for Agent-type processes. Folder context is inferred from the job key."
      },
      {
        "Name": "healing-data [options] <job-key>",
        "Description": "Download healing agent (Autopilot for Robots) recovery data as a ZIP file. Contains screenshots, UI element data, and recovery logs. Only available for jobs where the healing agent was active. Triggers an async export, polls until complete, then downloads the ZIP."
      },
      {
        "Name": "history [options] <job-key>",
        "Description": "Get state transition history for a job. Shows timestamps for each state change (Pending → Running → Successful/Faulted). Useful for understanding job lifecycle and identifying delays. Folder context is resolved automatically from the job key."
      },
      {
        "Name": "help [command]",
        "Description": "display help for command"
      }
    ],
    "GlobalOptions": [
      {
        "Flags": "--output <table|json|yaml|plain>",
        "Description": "Output format (default: json)"
      },
      {
        "Flags": "--output-filter <expression>",
        "Description": "JMESPath expression to filter output"
      },
      {
        "Flags": "--log-level <debug|info|warn|error>",
        "Description": "Log level threshold (default: info)"
      },
      {
        "Flags": "--log-file <path>",
        "Description": "Write logs to file instead of stderr"
      }
    ]
  }
